import {TripEngine,distance,validPoint,validTrip,MAX_AGE} from './engine.js';
import {searchStations,nearbyStops,findRoutes} from './data.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
